//
// Postconditions:
// - The operation returns the referenced Item.
OCL:

contract:
Contract ManageItemCRUDService::queryItem(barcode:Integer): Item {
          precondition:
          Item.allInstances()->exists(i: Item | i.Barcode = barcode)
            postcondition:
          result = Item.allInstances()->any(i: Item | i.Barcode = barcode)

        }

