// Operation: LibraryManagementSystemSystem::payOverDueFee(uid: String, fee: Real): Boolean
// Specification:
// Operation intent:
// Pay the outstanding overdue fee for a user and the associated returned overdue loans.
//
// Preconditions:
// - The User exists and has returned overdue loans with positive fees.
// - The supplied payment covers the user total overdue fee.
//
// Postconditions:
// - The User overdue fee and each applicable Loan overdue fee become zero.
// - The operation returns true.
OCL:

contract:
Contract LibraryManagementSystemSystem::payOverDueFee(uid:String,fee:Real): Boolean {
          precondition:
          User.allInstances()->exists(u |
        u.UserID = uid and
        u.LoanedBook->exists(l |
            l.IsReturned = true and
            l.OverDueFee > 0
        )
    ) and
User.allInstances()->exists(u |
        u.UserID = uid and
        fee >= u.OverDueFee
    )
            postcondition:
          User.allInstances()->forAll(u |
        u.UserID = uid implies
            u.OverDueFee = 0
    ) and
User.allInstances()->forAll(u |
        u.UserID = uid implies
            u.LoanedBook@pre->select(l |
                l.IsReturned = true and
                l.OverDueFee@pre > 0
            )->forAll(l |
                l.OverDueFee = 0
            )
    ) and
result = true

        }

